const plans = {
 job:{title:"A simple job-search plan",steps:[["Get clear on your target","Write down the kind of role, schedule, or workplace you want."],["Prepare one useful document","Gather your experience and update a resume or work history."],["Reach out to one resource","Try FEC for Missouri-side services or Workforce Partnership for its Kansas-side service area; confirm eligibility directly."]]},
 skills:{title:"A digital-skills starter plan",steps:[["Choose one skill to practice","Pick a task you want to feel more confident doing, like email or online forms."],["Find a learning option","Explore Literacy KC digital-literacy programs or ask a KCK Public Library branch about computer access and one-on-one help."],["Practice with a real task","Set aside 20 minutes to apply the skill and note what you want to learn next."]]},
 training:{title:"A training exploration plan",steps:[["Name your goal","Write down the role or skill you want training to help you reach."],["Compare two programs","Check total cost, time, prerequisites, format, and whether employers recognize it."],["Ask about funding first","Contact FEC or Workforce Partnership based on your area and ask whether you may qualify for training support before enrolling."]]},
 support:{title:"A community-support plan",steps:[["Decide what kind of help you need","You do not need to share sensitive personal details on this page."],["Start with 211","Ask United Way 211 about local food, housing, utility, health, childcare, or transportation resources."],["Confirm the next step","Check current eligibility, availability, costs, and what to bring directly with the provider."]]}
};

if (typeof document !== "undefined" && document.body.dataset.categoryPage) {
 const categoryName = document.body.dataset.categoryPage;
 const grid = document.querySelector("#resource-grid");
 const search = document.querySelector("#search");
 const count = document.querySelector("#result-count");
 const renderCategoryResources = () => {
  const query = search.value.trim().toLowerCase();
  const filtered = resources.filter(resource => resource.category === categoryName && (resource.title+" "+resource.description+" "+resource.tag+" "+resource.region+" "+resource.contact).toLowerCase().includes(query));
  count.textContent = filtered.length+" resource"+(filtered.length===1?"":"s");
  if (!filtered.length) {
   grid.innerHTML = '<div class="empty-state"><b>No matches just yet.</b><p>Try another search phrase.</p></div>';
   return;
  }
  grid.innerHTML = filtered.map(resource => '<article class="resource-card"><div class="resource-top"><span class="resource-icon" aria-hidden="true">'+resource.icon+'</span><span class="resource-category">'+resource.category+'</span></div><h3>'+resource.title+'</h3><p>'+resource.description+'</p><p><b>Area:</b> '+resource.region+'</p><p><b>Contact:</b> '+resource.contact+'</p><div class="resource-footer"><span>'+resource.tag+'</span><a href="'+resource.url+'" target="_blank" rel="noopener noreferrer">Official site ↗</a></div></article>').join("");
 };
 search.addEventListener("input",renderCategoryResources);
 document.querySelector("#clear-filters").addEventListener("click",()=>{search.value="";renderCategoryResources();search.focus();});
 renderCategoryResources();
} else if (document.querySelector("#goal")) {

let activeCategory = "All";
const grid = document.querySelector("#resource-grid");
const search = document.querySelector("#search");
function renderResources(){
 const q = search.value.trim().toLowerCase();
 const filtered = resources.filter(r => (activeCategory==="All"||r.category===activeCategory) && (r.title+" "+r.description+" "+r.category+" "+r.tag+" "+r.region).toLowerCase().includes(q));
 document.querySelector("#result-count").textContent = filtered.length+" resource"+(filtered.length===1?"":"s");
 if(!filtered.length){grid.innerHTML='<div class="empty-state"><b>No matches just yet.</b><p>Try another phrase or reset the filters.</p></div>';return;}
 grid.innerHTML = filtered.map(r=>'<article class="resource-card"><div class="resource-top"><span class="resource-icon" aria-hidden="true">'+r.icon+'</span><span class="resource-category">'+r.category+'</span></div><h3>'+r.title+'</h3><p>'+r.description+'</p><p><b>Area:</b> '+r.region+'</p><p><b>Contact:</b> '+r.contact+'</p><div class="resource-footer"><span>'+r.tag+'</span><a href="'+r.url+'" target="_blank" rel="noopener noreferrer" aria-label="Visit official website for '+r.title+'">Official site ↗</a></div></article>').join("");
}
document.querySelectorAll(".filter").forEach(button=>button.addEventListener("click",()=>{
 activeCategory=button.dataset.category;
 document.querySelectorAll(".filter").forEach(b=>b.classList.toggle("active",b===button));
 renderResources();
}));
search.addEventListener("input",renderResources);
document.querySelector("#clear-filters").addEventListener("click",()=>{
 search.value="";activeCategory="All";
 document.querySelectorAll(".filter").forEach(b=>b.classList.toggle("active",b.dataset.category==="All"));
 renderResources();
});
function renderPlan(){
 const plan=plans[document.querySelector("#goal").value];
 document.querySelector("#plan-title").textContent=plan.title;
 document.querySelector("#plan-steps").innerHTML=plan.steps.map((s,i)=>'<li><span>'+(i+1)+'</span><div><b>'+s[0]+'</b><p>'+s[1]+'</p></div></li>').join("");
 document.querySelector("#plan-steps").dataset.goal=document.querySelector("#goal").value;
 document.querySelector("#saved-message").textContent="";
 document.querySelector("#save-plan").textContent="□ Save steps on this device";
}
document.querySelector("#make-plan").addEventListener("click",renderPlan);
document.querySelector("#goal").addEventListener("change",renderPlan);
document.querySelector("#save-plan").addEventListener("click",()=>{
 const key="bridge-kc-saved-plan";
 const goal=document.querySelector("#goal").value;
 try{
  const existing=localStorage.getItem(key);
  if(existing===goal){localStorage.removeItem(key);document.querySelector("#saved-message").textContent="Plan removed from this device.";document.querySelector("#save-plan").textContent="□ Save steps on this device";}
  else{localStorage.setItem(key,goal);document.querySelector("#saved-message").textContent="Plan saved in this browser on this device.";document.querySelector("#save-plan").textContent="✓ Saved on this device";}
 }catch(e){document.querySelector("#saved-message").textContent="Local storage is unavailable in this browser session.";}
});
document.querySelector("#feedback-form").addEventListener("submit",e=>{
 e.preventDefault();
 document.querySelector("#feedback-message").textContent="Thanks—your choice is shown only in this demo. It has not been sent or stored.";
 document.querySelector("#feedback").value="";
});
renderResources();
try{if(localStorage.getItem("bridge-kc-saved-plan")){document.querySelector("#saved-message").textContent="A plan is saved in this browser.";document.querySelector("#save-plan").textContent="✓ Saved on this device";}}catch(e){}

}

const supportForm = document.querySelector("#support-form");
if (supportForm) {
 supportForm.addEventListener("submit", event => {
  event.preventDefault();
  const offer = document.querySelector("#support-type").value;
  const name = document.querySelector("#support-name").value.trim() || "Not provided";
  const contact = document.querySelector("#support-contact").value.trim() || "Not provided";
  const message = document.querySelector("#support-message").value.trim();
  const subject = "[BRIDGE KC community offer] " + offer;
  const body = [
   "Community support offer",
   "",
   "Offer type: " + offer,
   "Name / organization: " + name,
   "Contributor contact: " + contact,
   "",
   "Details:",
   message,
   "",
   "Submitted through the BRIDGE KC website. Please verify details before adding information to the public directory."
  ].join("\n");
  const mailto = "mailto:bridgekc186@gmail.com?subject=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
  document.querySelector("#support-message-status").textContent =
   "Your email draft is ready. Review it in your email app and press Send. Nothing is sent automatically; please do not include confidential information.";
  window.location.href = mailto;
 });
}


const careerQuiz = document.querySelector("#career-quiz");
if (careerQuiz) {
 careerQuiz.addEventListener("submit", event => {
  event.preventDefault();
  const interest = document.querySelector("#quiz-interest").value;
  const style = document.querySelector("#quiz-style").value;
  const time = document.querySelector("#quiz-time").value;
  const barrier = document.querySelector("#quiz-barrier").value;
  const location = document.querySelector("#quiz-location").value;
  const map = {
   tech:{title:"Technology & IT",description:"Build practical skills for IT support, cybersecurity foundations, web development, or data roles. Compare program requirements and entry-level job postings before choosing a course.",links:[["i.c.stars Kansas City","https://www.icstars.org/location/kansas-city/"],["Per Scholas Kansas City","https://perscholas.org/locations/kansas-city/"],["MCC certificates","https://mcckc.edu/programs/certificates/"]]},
   health:{title:"Healthcare & patient support",description:"Compare short healthcare credentials such as CNA, phlebotomy, medical assistant, and patient care roles. Confirm clinical requirements, background checks, exam fees, and placement support.",links:[["Great Jobs KC training pathways","https://greatjobskc.org/skills-training/"],["MCC certificates","https://mcckc.edu/programs/certificates/"],["Great Jobs KC application","https://greatjobskc.org/apply/"]]},
   trades:{title:"Skilled trades & building systems",description:"Explore electrical, HVAC, construction, welding, and maintenance training. Registered apprenticeships may combine paid work with classroom learning.",links:[["Missouri apprenticeships","https://jobs.mo.gov/moapprenticeships"],["Workforce Partnership job seeker services","https://workforcepartnership.com/job-seeker-services/"],["KCKCC workforce programs","https://www.kckcc.edu/academics/workforce-innovation/workforce-development-programs.html"]]},
   logistics:{title:"Logistics, transportation & operations",description:"Explore warehouse operations, inventory, CDL routes, and supply-chain roles. Check license costs, medical requirements, shift times, and current local job postings.",links:[["Great Jobs KC training pathways","https://greatjobskc.org/skills-training/"],["Workforce Partnership job seeker services","https://workforcepartnership.com/job-seeker-services/"],["KansasWorks","https://www.kansasworks.com/"]]},
   office:{title:"Business & office support",description:"Explore customer service, administrative support, bookkeeping, and office software credentials. Create a resume and one practical work sample alongside training.",links:[["MCC certificates","https://mcckc.edu/programs/certificates/"],["Full Employment Council","https://www.feckc.org/"],["Workforce Partnership job seeker services","https://workforcepartnership.com/job-seeker-services/"]]},
   manufacturing:{title:"Manufacturing, maintenance & quality",description:"Explore machine operation, industrial maintenance, production, and quality roles. Ask employers and workforce centers about paid training, safety credentials, and apprenticeship openings.",links:[["Great Jobs KC training pathways","https://greatjobskc.org/skills-training/"],["KCKCC workforce programs","https://www.kckcc.edu/academics/workforce-innovation/workforce-development-programs.html"],["Missouri apprenticeships","https://jobs.mo.gov/moapprenticeships"]]},
   people:{title:"Community support & people-facing work",description:"Explore community services, childcare, education support, and healthcare support. Requirements differ by role, so check background checks, licenses, and required experience early.",links:[["Great Jobs KC training pathways","https://greatjobskc.org/skills-training/"],["Kansas adult career pathways","https://kansasregents.gov/workforce_development/adult-education/accelerating-opportunity-kansas"],["United Way 211 KC","https://211kc.org/"]]}
  };
  const chosen = map[interest];
  const timeNote = time === "fast" ? "Your short timeline: first look for paid onboarding, short certificates, employer training, and apprenticeship openings. Avoid enrolling until you know the full time and cost." : time === "mid" ? "Your 3–9 month timeline: compare certificate length, class schedule, completion rates if published, employer connections, and funding before choosing." : "Your longer timeline: compare stackable credentials and advancement potential, but choose a longer program only if the job outcomes justify the time and cost.";
  const styleNote = style === "hands" ? "Learning fit: prioritize hands-on labs, clinical practice, shop time, ride-alongs, or paid on-the-job learning." : style === "class" ? "Learning fit: prioritize structured classes with a recognized certificate or exam and clear instructor support." : style === "project" ? "Learning fit: ask for portfolio projects, practical demonstrations, or work samples you can show an employer." : "Learning fit: ask about coaching, mentoring, small-group instruction, and a named person to contact when you get stuck.";
  const barrierNote = barrier === "free" ? "Cost priority: contact a workforce center before enrolling. Ask whether the exact program is currently funded through Great Jobs KC, WIOA, SNAP-linked SkillUP, or another program; approval, eligibility, and extra costs vary." : barrier === "paid" ? "Earn-while-learning priority: ask about registered apprenticeships, paid training, employer tuition support, wages during training, and whether tools or exams are your responsibility." : barrier === "stable" ? "Stability priority: compare local job openings, benefits, predictable schedules, physical requirements, and employer retention—not just the certificate title." : barrier === "growth" ? "Growth priority: ask what the next credential or promotion is, typical experience requirements, and whether the first credential stacks toward a higher-paying role." : "Flexibility priority: ask about evening/weekend classes, remote components, attendance rules, and how much in-person practice is mandatory.";
  const area = location === "mo" ? "Location fit: start with Missouri-side providers and the Full Employment Council. Ask about Missouri residency rules and which training providers are approved for funding." : location === "ks" ? "Location fit: start with Kansas-side providers and Workforce Partnership/KansasWorks. Ask about county service areas and Kansas funding requirements." : "Location fit: compare both sides of the metro. Training funds often depend on residence, county, and workforce-board rules, so ask before enrolling across state lines.";
  const priorityLink = barrier === "free" ? [["Great Jobs KC eligibility and programs","https://greatjobskc.org/skills-training/"],["Great Jobs KC application","https://greatjobskc.org/apply/"]] : barrier === "paid" ? [["Workforce Partnership apprenticeships and job seeker services","https://workforcepartnership.com/job-seeker-services/"],["Missouri apprenticeships","https://jobs.mo.gov/moapprenticeships"]] : barrier === "flex" ? [["Full Employment Council","https://www.feckc.org/"],["Workforce Partnership job seeker services","https://workforcepartnership.com/job-seeker-services/"]] : [["Full Employment Council","https://www.feckc.org/"],["Workforce Partnership job seeker services","https://workforcepartnership.com/job-seeker-services/"]];
  const allLinks = [...chosen.links, ...priorityLink].filter((item, index, array) => array.findIndex(other => other[1] === item[1]) === index);
  const links = allLinks.map(link => '<li><a href="' + link[1] + '" target="_blank" rel="noopener noreferrer">' + link[0] + ' ↗</a></li>').join("");
  const regionLabel = location === "mo" ? "Missouri side" : location === "ks" ? "Kansas side" : "Both sides of the metro";
  const result = document.querySelector("#quiz-results");
  result.innerHTML = '<span class="pathway-label">Your personalized starting point · ' + regionLabel + '</span><h3>' + chosen.title + '</h3><p>' + chosen.description + '</p><h4>Resources matched to your answers</h4><ul>' + links + '</ul><h4>Your learning and timeline fit</h4><ul><li>' + timeNote + '</li><li>' + styleNote + '</li><li>' + barrierNote + '</li><li>' + area + '</li></ul><h4>Your first 7 days</h4><ol><li><b>Day 1:</b> Open one training provider and write down the next start date, entry requirements, and contact method.</li><li><b>Days 2–3:</b> Ask whether this exact program is funded, what costs are not covered, and whether transportation, equipment, childcare, or internet support is available.</li><li><b>Days 4–5:</b> Find three local job postings for the target role. Compare their required skills and credentials with the course curriculum.</li><li><b>Days 6–7:</b> Choose one next action: attend an information session, request a workforce appointment, or apply if requirements and funding are clear.</li></ol><p class="verification-note"><b>Important:</b> These are starting points, not a guarantee of admission, funding, certification, or employment. Program availability, costs, eligibility, and start dates must be confirmed directly. Do not pay for a course until you understand total costs and funding approval.</p>';
  result.scrollIntoView({behavior:"smooth",block:"nearest"});
 });
}
